query:
mutation ($aggregateView: [CreatePurchaseOrderArgs!]!, $viewType: Float!, $company: Float!, $userId: String!, $notificationSettings: NotificationSettings) {
  createPOPPurchaseOrders(
    aggregateView: $aggregateView
    viewType: $viewType
    company: $company
    userId: $userId
    notificationSettings: $notificationSettings
  ) {
    status
    message
    __typename
  }
}
